import uuid
from collections import namedtuple

from kombu.serialization import dumps, loads, prepare_accept_content

from tasks import app

SentTask = namedtuple("SentTask", "name args kwargs task_id")


class FakeTaskQueue:
    def __init__(self):
        self.sent: list[SentTask] = []

    def send_task(self, name, args=None, kwargs=None, task_id=None, **options):
        content_type, encoding, body = dumps((args or (), kwargs or {}), serializer=app.conf.task_serializer)
        args, kwargs = loads(body, content_type, encoding, accept=prepare_accept_content(app.conf.accept_content))
        self.sent.append(SentTask(name, tuple(args), kwargs, task_id or str(uuid.uuid4())))
        return app.AsyncResult(self.sent[-1].task_id)

    def drain(self) -> list:
        results = []
        while self.sent:
            task = self.sent.pop(0)
            results.append(app.tasks[task.name].apply(task.args, task.kwargs, task_id=task.task_id).get(propagate=True))
        return results
